class Solution:
    def countVisibleAssignments(self, n, pos, k):
        MOD = 10**9 + 7
        L, R = pos, n - 1 - pos
        if k > L + R:
            return 0
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i-1] * i % MOD
        inv_fact = [1] * (n + 1)
        inv_fact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv_fact[i-1] = inv_fact[i] * i % MOD
        def C(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a-b] % MOD
        ans = 0
        for a in range(max(0, k - R), min(L, k) + 1):
            ans = (ans + C(L, a) * C(R, k - a)) % MOD
        return ans * 2 % MOD

