class Solution {
public:
    int countVisibleAssignments(int n, int pos, int k) {
        const long long MOD = 1e9 + 7;
        int L = pos, R = n - 1 - pos;
        if (k > L + R) return 0;
        vector<long long> fact(n + 1, 1), inv(n + 1, 1);
        for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
        auto pw = [&](long long b, long long e) {
            long long r = 1; b %= MOD;
            while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
            return r;
        };
        inv[n] = pw(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
        auto C = [&](int a, int b) -> long long {
            if (b < 0 || b > a) return 0;
            return fact[a] * inv[b] % MOD * inv[a-b] % MOD;
        };
        long long ans = 0;
        for (int a = max(0, k - R); a <= min(L, k); a++)
            ans = (ans + C(L, a) * C(R, k - a)) % MOD;
        return ans * 2 % MOD;
    }
};

