class Solution {
    public int countVisibleAssignments(int n, int pos, int k) {
        final long MOD = 1_000_000_007L;
        int L = pos, R = n - 1 - pos;
        if (k > L + R) return 0;
        long[] fact = new long[n + 1], inv = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
        inv[n] = pow(fact[n], MOD - 2, MOD);
        for (int i = n; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
        long ans = 0;
        for (int a = Math.max(0, k - R); a <= Math.min(L, k); a++)
            ans = (ans + C(L, a, fact, inv, MOD) * C(R, k - a, fact, inv, MOD)) % MOD;
        return (int)(ans * 2 % MOD);
    }
    private long pow(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
    private long C(int a, int b, long[] fact, long[] inv, long m) {
        if (b < 0 || b > a) return 0;
        return fact[a] * inv[b] % m * inv[a-b] % m;
    }
}

