var countVisibleAssignments = function(n, pos, k) {
    const MOD = 1e9 + 7;
    const L = pos, R = n - 1 - pos;
    if (k > L + R) return 0;
    const fact = new Array(n + 1).fill(1), inv = new Array(n + 1).fill(1);
    for (let i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
    const pw = (b, e) => { let r = 1; b %= MOD; while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e = Math.floor(e / 2); } return r; };
    inv[n] = pw(fact[n], MOD - 2);
    for (let i = n; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
    const C = (a, b) => (b < 0 || b > a) ? 0 : fact[a] * inv[b] % MOD * inv[a-b] % MOD;
    let ans = 0;
    for (let a = Math.max(0, k - R); a <= Math.min(L, k); a++)
        ans = (ans + C(L, a) * C(R, k - a)) % MOD;
    return ans * 2 % MOD;
};
